# Initialize the to-do list with an empty string
to_do_list = []

def add_item():
    """Add an item to the to-do list."""
    global to_do_list
    item = input("Enter an item to add to the to-do list (or type 'done' to complete an item): ").strip()
    if item.lower() == "done":
        # Remove the last item from the list if there is one
        if to_do_list:
            to_do_list.pop()
    else:
        to_do_list.append(item)

def print_list():
    """Print the current to-do list."""
    global to_do_list
    if not to_do_list:
        print("Your to-do list is currently empty.")
    else:
        print("Your to-do list:")
        for i, item in enumerate(to_do_list, start=1):
            print(f"{i}. {item}")

def remove_item():
    """Remove an item from the to-do list."""
    global to_do_list
    index = int(input("Enter the index of the item to remove (or type 'done' to complete an item): "))
    if index == len(to_do_list):
        # Remove the last item from the list if it's 'done'
        if to_do_list[-1].lower() == "done":
            to_do_list.pop()
        else:
            to_do_list.pop()
    else:
        to_do_list.pop(index - 1)

# Main loop
while True:
    print("\nAvailable actions:")
    print("1. Add an item")
    print("2. Print the to-do list")
    print("3. Remove an item")
    print("4. Quit")

